components.css:
.ds-btn-primary{background:#633481;color:#FEFCFD;font-family:'IBM Plex Sans', system-ui, sans-serif;font-size:.75rem;font-weight:500;letter-spacing:.01em;height:36px;padding:0 16px;border:none;border-radius:5px;cursor:pointer;transition:background 120ms cubic-bezier(0.25, 1, 0.5, 1);}
.ds-btn-primary:hover{background:#521D71;}
.ds-btn-primary:focus-visible{outline: 2px solid #633481; outline-offset: 2px; box-shadow: 0 0 0 3px rgba(99,52,129,0.20);}
.ds-btn-primary:active{background:#521D71;}
.ds-btn-primary:disabled{opacity:.45;cursor:not-allowed;}

.ds-btn-secondary{background:#FEFCFD;color:#20171D;font-family:'IBM Plex Sans', system-ui, sans-serif;font-size:.75rem;font-weight:500;letter-spacing:.01em;height:36px;padding:0 16px;border:1px solid #91898E;border-radius:5px;cursor:pointer;transition:background 120ms cubic-bezier(0.25, 1, 0.5, 1);}
.ds-btn-secondary:hover{background:#F1EBEE;}
.ds-btn-secondary:focus-visible{outline: 2px solid #633481; outline-offset: 2px; box-shadow: 0 0 0 3px rgba(99,52,129,0.20);}
.ds-btn-secondary:disabled{opacity:.45;cursor:not-allowed;}

.ds-field{display:flex;flex-direction:column;gap:6px;font-family:'IBM Plex Sans', system-ui, sans-serif;}
.ds-field-label{font-size:.75rem;font-weight:500;letter-spacing:.01em;color:#5B5258;}
.ds-field-input{background:#FEFCFD;color:#20171D;font-family:'IBM Plex Sans', system-ui, sans-serif;font-size:.875rem;font-variant-numeric:tabular-nums;text-align:right;height:36px;padding:0 12px;border:1px solid #91898E;border-radius:5px;transition:border-color 120ms cubic-bezier(0.25, 1, 0.5, 1);}
.ds-field-input::placeholder{color:#746C71;}
.ds-field-input:focus{border-color:#633481;outline: 2px solid #633481; outline-offset: 2px; box-shadow: 0 0 0 3px rgba(99,52,129,0.20);}
.ds-field-input:disabled{background:#F1EBEE;color:#746C71;}

.ds-nav{display:flex;flex-direction:column;gap:2px;background:#F1EBEE;padding:8px;width:240px;font-family:'IBM Plex Sans', system-ui, sans-serif;}
.ds-nav-item{display:flex;align-items:center;gap:10px;height:34px;padding:0 12px;border-radius:5px;font-size:.875rem;color:#5B5258;text-decoration:none;transition:background 120ms cubic-bezier(0.25, 1, 0.5, 1);}
.ds-nav-item:hover{background:#FEFCFD;}
.ds-nav-item:focus-visible{outline: 2px solid #633481; outline-offset: 2px; box-shadow: 0 0 0 3px rgba(99,52,129,0.20);}
.ds-nav-item.is-active{background:#F3EBFA;color:#633481;font-weight:500;}

.ds-chips{display:flex;gap:8px;flex-wrap:wrap;font-family:'IBM Plex Sans', system-ui, sans-serif;}
.ds-chip{display:inline-flex;align-items:center;gap:4px;font-size:.6875rem;letter-spacing:.01em;padding:2px 8px;border-radius:3px;border:1px solid transparent;white-space:nowrap;}
.ds-chip-critical{background:#FFECE9;color:#B71824;border-color:#FDC9C4;}
.ds-chip-warning{background:#FDF1D9;color:#975800;border-color:#F2D5A5;}
.ds-chip-success{background:#E1F8EB;color:#00713E;border-color:#BAE3CA;}
.ds-chip-neutral{background:#F1EBEE;color:#5B5258;border-color:#E5DFE3;}

.ds-table{border-collapse:collapse;width:100%;font-family:'IBM Plex Sans', system-ui, sans-serif;font-size:.875rem;background:#FEFCFD;border:1px solid #E5DFE3;border-radius:5px;overflow:hidden;}
.ds-table th{background:#FAF5F8;color:#746C71;font-size:.75rem;font-weight:500;letter-spacing:.01em;text-align:left;height:36px;padding:0 16px;border-bottom:1px solid #E5DFE3;}
.ds-table td{color:#20171D;height:48px;padding:0 16px;border-bottom:1px solid #E5DFE3;}
.ds-table tbody tr:last-child td{border-bottom:none;}
.ds-table tbody tr{transition:background 120ms cubic-bezier(0.25, 1, 0.5, 1);}
.ds-table tbody tr:hover{background:#FAF5F8;}
.ds-table .num{text-align:right;font-variant-numeric:tabular-nums;}
.ds-table .mono{font-family:'IBM Plex Mono', ui-monospace, monospace;font-size:.8125rem;letter-spacing:-.01em;color:#5B5258;}
.ds-t-chip{display:inline-block;font-size:.6875rem;padding:2px 8px;border-radius:3px;background:#F1EBEE;color:#5B5258;border:1px solid #E5DFE3;}

.ds-val{background:#FEFCFD;border:1px solid #E5DFE3;border-radius:5px;padding:20px;font-family:'IBM Plex Sans', system-ui, sans-serif;max-width:440px;animation:ds-val-in 300ms cubic-bezier(0.25, 1, 0.5, 1) both;}
@keyframes ds-val-in{from{opacity:0;transform:translateY(6px);}to{opacity:1;transform:none;}}
@media (prefers-reduced-motion: reduce){.ds-val{animation-duration:.01ms;animation-name:ds-val-fade;}@keyframes ds-val-fade{from{opacity:0;}to{opacity:1;}}}
.ds-val-head{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:16px;}
.ds-val-title{font-size:1rem;font-weight:600;color:#20171D;margin:0;}
.ds-val-hero{font-size:2.5rem;font-weight:600;line-height:1;letter-spacing:-.02em;font-variant-numeric:tabular-nums;color:#975800;margin:0;}
.ds-val-heroSub{font-size:.8125rem;color:#5B5258;margin:6px 0 20px;font-variant-numeric:tabular-nums;}
.ds-val-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin:0 0 16px;padding-top:16px;border-top:1px solid #E5DFE3;}
.ds-val-grid dt{font-size:.75rem;font-weight:500;letter-spacing:.01em;color:#5B5258;margin-bottom:4px;}
.ds-val-grid dd{font-size:1.5rem;font-weight:600;line-height:1.1;letter-spacing:-.01em;font-variant-numeric:tabular-nums;color:#20171D;margin:0;}
.ds-val-grid dd.muted{color:#746C71;}
.ds-val-src{font-size:.6875rem;color:#746C71;margin:0;}
.ds-chip{display:inline-flex;align-items:center;gap:4px;font-size:.6875rem;padding:2px 8px;border-radius:3px;border:1px solid transparent;white-space:nowrap;}
.ds-chip-warning{background:#FDF1D9;color:#975800;border-color:#F2D5A5;}

.ds-block{display:flex;gap:10px;background:#FFECE9;border:1px solid #FDC9C4;border-radius:5px;padding:12px 14px;font-family:'IBM Plex Sans', system-ui, sans-serif;max-width:440px;}
.ds-block-i{color:#B71824;flex:none;margin-top:1px;}
.ds-block-t{font-size:.875rem;font-weight:600;color:#B71824;margin:0 0 4px;}
.ds-block-l{margin:0 0 8px;padding-left:16px;font-size:.8125rem;color:#20171D;}
.ds-block-a{font-size:.8125rem;font-weight:500;color:#633481;text-decoration:underline;text-underline-offset:2px;}
.ds-block-a:focus-visible{outline: 2px solid #633481; outline-offset: 2px; box-shadow: 0 0 0 3px rgba(99,52,129,0.20);}
